-- Explicit maintenance SQL. Validate the confirmed database binding first.
CREATE INDEX IF NOT EXISTS scene_qualifications_lookup ON scene_qualifications(account_id,policy_id,profile_id,expires_at);

CREATE TABLE IF NOT EXISTS community_schema_revision(
    slot INTEGER PRIMARY KEY CHECK(slot=1),revision INTEGER NOT NULL CHECK(revision>=1),
    contract TEXT NOT NULL,installed_at INTEGER NOT NULL);

INSERT INTO community_schema_revision(slot,revision,contract,installed_at)
    SELECT 1,CASE WHEN ((SELECT COUNT(*) FROM pragma_table_info('accounts') WHERE name IN ('id','token_hash','units','recovery_hash','deleted_at'))=5 AND (SELECT COUNT(*) FROM pragma_table_info('locations') WHERE name IN ('id','asset_id','capture','lane','model','state','active_lease','lease_until','output_sha256','contributor_id','source','rights','attribution','lat','lon','heading','pitch','zoom','country','camera_generation','generation','queue_state','catalog_shard'))=23 AND (SELECT COUNT(*) FROM pragma_table_info('leases') WHERE name IN ('id','account_id','lane','expires_at','state','generation','pace','scene_qualification_id'))=8 AND (SELECT COUNT(*) FROM pragma_table_info('lease_items') WHERE name IN ('lease_id','location_id'))=2 AND (SELECT COUNT(*) FROM pragma_table_info('published_index') WHERE name IN ('location_id','index_text','output_sha256','published_at','embedding','segment_id','four_view_sha256','four_view_key','object_index_sha256','object_index_key'))=10 AND (SELECT COUNT(*) FROM pragma_table_info('ledger') WHERE name IN ('id','account_id','units','reason','reference'))=5 AND (SELECT COUNT(*) FROM pragma_table_info('searches') WHERE name IN ('id','account_id','idempotency_key','query','result_json'))=5 AND (SELECT COUNT(*) FROM pragma_table_info('pose_catalog') WHERE name IN ('lane','shard_id','r2_key','row_start','row_count','bytes','sha256','next_byte','next_row','assignee','assigned_at','held'))=12 AND (SELECT COUNT(*) FROM pragma_table_info('index_shards') WHERE name IN ('r2_key','lane','location_count','bytes','sha256','created_at'))=6 AND (SELECT COUNT(*) FROM pragma_table_info('object_coverage') WHERE name IN ('location_id','validator','evidence_sha256','validated_at'))=4 AND (SELECT COUNT(*) FROM pragma_table_info('scene_qualifications') WHERE name IN ('id','account_id','profile_id','policy_id','canary_sha256','expires_at','created_at'))=7 AND (SELECT COUNT(*) FROM pragma_table_info('scene_candidates') WHERE name IN ('lease_id','account_id','qualification_id','policy_id','submission_sha256','artifact_key','records_json','created_at','state'))=9 AND (SELECT COUNT(*) FROM pragma_table_info('account_artifact_writes') WHERE name IN ('artifact_key','account_id','lease_id','sha256','bytes','created_at'))=6 AND (SELECT COUNT(*) FROM pragma_table_info('account_deletion_receipts') WHERE name IN ('account_id','request_key','deleted_at','units_forfeited'))=4 AND (SELECT COUNT(*) FROM pragma_table_info('account_cleanup') WHERE name IN ('artifact_key','account_id','created_at','state'))=4 AND (SELECT COUNT(*) FROM pragma_table_info('account_deletion_archives') WHERE name IN ('account_id','sha256','archived_at'))=3 AND EXISTS(SELECT 1 FROM sqlite_master WHERE type='trigger' AND name='deleted_account_cannot_reactivate' AND replace(lower(replace(replace(replace(replace(replace(replace(sql,'IF NOT EXISTS',''),'if not exists',''),' ',''),char(10),''),char(13),''),char(9),'')),';','')='createtriggerdeleted_account_cannot_reactivatebeforeupdateonaccountswhenold.deleted_atisnotnulland(new.deleted_atisnullornew.token_hash!=old.token_hashornew.recovery_hashisnotnullornew.units!=0)beginselectraise(abort,''account_not_active'')end') AND EXISTS(SELECT 1 FROM sqlite_master WHERE type='trigger' AND name='ledger_active_account_insert' AND replace(lower(replace(replace(replace(replace(replace(replace(sql,'IF NOT EXISTS',''),'if not exists',''),' ',''),char(10),''),char(13),''),char(9),'')),';','')='createtriggerledger_active_account_insertbeforeinsertonledgerwhennotexists(select1fromaccountswhereid=new.account_idanddeleted_atisnull)beginselectraise(abort,''account_not_active'')end') AND EXISTS(SELECT 1 FROM sqlite_master WHERE type='trigger' AND name='searches_active_account_insert' AND replace(lower(replace(replace(replace(replace(replace(replace(sql,'IF NOT EXISTS',''),'if not exists',''),' ',''),char(10),''),char(13),''),char(9),'')),';','')='createtriggersearches_active_account_insertbeforeinsertonsearcheswhennotexists(select1fromaccountswhereid=new.account_idanddeleted_atisnull)beginselectraise(abort,''account_not_active'')end') AND EXISTS(SELECT 1 FROM sqlite_master WHERE type='trigger' AND name='scene_qualifications_active_account_insert' AND replace(lower(replace(replace(replace(replace(replace(replace(sql,'IF NOT EXISTS',''),'if not exists',''),' ',''),char(10),''),char(13),''),char(9),'')),';','')='createtriggerscene_qualifications_active_account_insertbeforeinsertonscene_qualificationswhennotexists(select1fromaccountswhereid=new.account_idanddeleted_atisnull)beginselectraise(abort,''account_not_active'')end') AND EXISTS(SELECT 1 FROM sqlite_master WHERE type='trigger' AND name='scene_candidates_active_account_insert' AND replace(lower(replace(replace(replace(replace(replace(replace(sql,'IF NOT EXISTS',''),'if not exists',''),' ',''),char(10),''),char(13),''),char(9),'')),';','')='createtriggerscene_candidates_active_account_insertbeforeinsertonscene_candidateswhennotexists(select1fromaccountswhereid=new.account_idanddeleted_atisnull)beginselectraise(abort,''account_not_active'')end') AND EXISTS(SELECT 1 FROM sqlite_master WHERE type='trigger' AND name='leases_active_account_insert' AND replace(lower(replace(replace(replace(replace(replace(replace(sql,'IF NOT EXISTS',''),'if not exists',''),' ',''),char(10),''),char(13),''),char(9),'')),';','')='createtriggerleases_active_account_insertbeforeinsertonleaseswhennotexists(select1fromaccountswhereid=new.account_idanddeleted_atisnull)beginselectraise(abort,''account_not_active'')end') AND EXISTS(SELECT 1 FROM sqlite_master WHERE type='trigger' AND name='account_artifact_writes_active_account_insert' AND replace(lower(replace(replace(replace(replace(replace(replace(sql,'IF NOT EXISTS',''),'if not exists',''),' ',''),char(10),''),char(13),''),char(9),'')),';','')='createtriggeraccount_artifact_writes_active_account_insertbeforeinsertonaccount_artifact_writeswhennotexists(select1fromaccountswhereid=new.account_idanddeleted_atisnull)begin