date' AND replace(lower(replace(replace(replace(replace(replace(replace(sql,'IF NOT EXISTS',''),'if not exists',''),' ',''),char(10),''),char(13),''),char(9),'')),';','')='createtriggercandidates_active_account_updatebeforeupdateonscene_candidateswhennew.statein(''pending'',''published'')andnotexists(select1fromaccountswhereid=new.account_idanddeleted_atisnull)beginselectraise(abort,''account_not_active'')end') AND EXISTS(SELECT 1 FROM sqlite_master WHERE type='trigger' AND name='catalog_active_assignee' AND replace(lower(replace(replace(replace(replace(replace(replace(sql,'IF NOT EXISTS',''),'if not exists',''),' ',''),char(10),''),char(13),''),char(9),'')),';','')='createtriggercatalog_active_assigneebeforeupdateofassigneeonpose_catalogwhennew.assigneeisnotnullandexists(select1fromaccountswhereid=new.assigneeanddeleted_atisnotnull)beginselectraise(abort,''account_not_active'')end') AND EXISTS(SELECT 1 FROM sqlite_master WHERE type='trigger' AND name='locations_active_contributor' AND replace(lower(replace(replace(replace(replace(replace(replace(sql,'IF NOT EXISTS',''),'if not exists',''),' ',''),char(10),''),char(13),''),char(9),'')),';','')='createtriggerlocations_active_contributorbeforeupdateonlocationswhennew.state=''published''and(old.state!=''published''ornew.contributor_idisnotold.contributor_id)andexists(select1fromaccountswhereid=new.contributor_idanddeleted_atisnotnull)beginselectraise(abort,''account_not_active'')end') AND EXISTS(SELECT 1 FROM sqlite_master WHERE type='trigger' AND name='locations_active_lease' AND replace(lower(replace(replace(replace(replace(replace(replace(sql,'IF NOT EXISTS',''),'if not exists',''),' ',''),char(10),''),char(13),''),char(9),'')),';','')='createtriggerlocations_active_leasebeforeupdateofactive_leaseonlocationswhennew.active_leaseisnotnullandexists(select1fromleasesljoinaccountsaona.id=l.account_idwherel.id=new.active_leaseanda.deleted_atisnotnull)beginselectraise(abort,''account_not_active'')end') AND (SELECT COUNT(*) FROM sqlite_master WHERE type='index' AND name IN ('locations_queue','locations_part_queue','scene_qualifications_lookup','account_artifact_writes_owner','published_index_four_view_key','account_cleanup_pending'))=6) AND NOT EXISTS
      (SELECT 1 FROM community_schema_revision WHERE revision>1 OR contract!='vision-community-d1-v1-20261004')
